package com.example.commerce.coupon; import static org.junit.jupiter.api.Assertions.*; import java.math.BigDecimal; import java.time.Instant; import com.example.commerce.common.CommerceException; import org.junit.jupiter.api.Test;
class CouponCalculatorTest {private final CouponCalculator calculator=new CouponCalculator();@Test void capsPercentageDiscount(){Coupon c=coupon(Coupon.Type.PERCENTAGE,"50");c.setMaximumDiscount(new BigDecimal("20"));assertEquals(new BigDecimal("20.00"),calculator.discount(c,new BigDecimal("100"),Instant.now()));}@Test void neverMakesTotalNegative(){Coupon c=coupon(Coupon.Type.FIXED,"150");assertEquals(new BigDecimal("100.00"),calculator.discount(c,new BigDecimal("100"),Instant.now()));}@Test void rejectsExpiredCoupon(){Coupon c=coupon(Coupon.Type.FIXED,"10");c.setExpiresAt(Instant.now().minusSeconds(1));assertThrows(CommerceException.class,()->calculator.discount(c,new BigDecimal("100"),Instant.now()));}private Coupon coupon(Coupon.Type t,String value){Coupon c=new Coupon();c.setType(t);c.setValue(new BigDecimal(value));c.setMinimumOrderValue(BigDecimal.ZERO);c.setActive(true);c.setStartsAt(Instant.now().minusSeconds(10));c.setExpiresAt(Instant.now().plusSeconds(10));return c;}}
